-- Top ten flagged account-months ranked by flagged gross, retaining P1/P2 rule priority and total candidate count. Order is exposure rank, not proof of fraud or predicted loss. Empty results mean no flags, not confirmed safety.
SELECT *, COUNT(*) OVER () AS total_candidate_accounts FROM finance.agent_demo_fs.account_risk_monthly_sql WHERE snapshot_id = (SELECT snapshot_id FROM finance.agent_demo_fs.snapshot_metadata_sql WHERE status = 'READY') AND period_key = CASE WHEN CAST({{period_key}} AS INT) = 0 THEN (SELECT MAX(period_key) FROM finance.agent_demo_fs.portfolio_monthly_sql WHERE snapshot_id = (SELECT snapshot_id FROM finance.agent_demo_fs.snapshot_metadata_sql WHERE status = 'READY')) ELSE CAST({{period_key}} AS INT) END AND flagged_count > 0 ORDER BY flagged_gross_usd DESC, flagged_count DESC, account_id LIMIT 10
